#[cfg(test)]
mod tests {
    use super::*;
    use futures_core::stream::BoxStream;
    use paigasus_helikon_core::{
        ContentPart, FinishReason, Item, ModelCapabilities, ModelError, ModelEvent, ModelSettings,
        ToolContext, ToolError, ToolOutput,
    };
    use serde_json::json;
    use std::sync::Mutex;
    use std::sync::OnceLock;

    // ---- error_kind_to_activity_error (ADR-10) ------------------------

    /// ADR-10: a model failure must be a **non-retryable** application error
    /// so Temporal's activity-retry machinery does not silently mask it — the
    /// workflow's `DurableDriver` must observe it as terminal. This is the
    /// embodiment of "the runner never retries model errors".
    #[test]
    fn error_kind_to_activity_error_model_is_non_retryable() {
        let err = error_kind_to_activity_error(ErrorKindPayload::Model {
            message: "connection lost".to_owned(),
        });
        match err {
            ActivityError::Application(app) => {
                assert!(
                    app.is_non_retryable(),
                    "ADR-10: model-failure activity errors must be non-retryable"
                );
            }
            other => panic!("expected ActivityError::Application, got {other:?}"),
        }
    }

    // ---- call_model_inner ---------------------------------------------

    struct ScriptedModel {
        events: Mutex<Option<Vec<Result<ModelEvent, ModelError>>>>,
    }

    impl ScriptedModel {
        fn new(events: Vec<Result<ModelEvent, ModelError>>) -> Self {
            Self {
                events: Mutex::new(Some(events)),
            }
        }
    }

    #[async_trait::async_trait]
    impl Model for ScriptedModel {
        async fn invoke(
            &self,
            _request: ModelRequest,
            _cancel: CancellationToken,
        ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
            let events = self.events.lock().unwrap().take().unwrap_or_default();
            Ok(Box::pin(futures_util::stream::iter(events)))
        }

        fn capabilities(&self) -> ModelCapabilities {
            ModelCapabilities::default()
        }
    }

    struct InvokeErrorModel;

    #[async_trait::async_trait]
    impl Model for InvokeErrorModel {
        async fn invoke(
            &self,
            _request: ModelRequest,
            _cancel: CancellationToken,
        ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
            Err(ModelError::Unavailable)
        }

        fn capabilities(&self) -> ModelCapabilities {
            ModelCapabilities::default()
        }
    }

    #[tokio::test]
    async fn call_model_inner_aggregates_happy_path() {
        let model = ScriptedModel::new(vec![
            Ok(ModelEvent::TokenDelta { text: "hel".into() }),
            Ok(ModelEvent::TokenDelta { text: "lo".into() }),
            Ok(ModelEvent::Usage {
                input_tokens: 3,
                output_tokens: 2,
                cached_input_tokens: None,
                reasoning_tokens: None,
            }),
            Ok(ModelEvent::Finish {
                reason: FinishReason::Stop,
            }),
        ]);

        let result = call_model_inner(
            &model,
            "agent-1",
            ModelRequest::new(),
            CancellationToken::new(),
        )
        .await
        .expect("happy path succeeds");

        assert_eq!(result.0.items.len(), 1);
        match &result.0.items[0] {
            Item::AssistantMessage { content, agent } => {
                assert_eq!(agent.as_deref(), Some("agent-1"));
                match &content[0] {
                    ContentPart::Text { text } => assert_eq!(text, "hello"),
                    other => panic!("expected Text, got {other:?}"),
                }
            }
            other => panic!("expected AssistantMessage, got {other:?}"),
        }
        assert_eq!(result.0.usage.input_tokens, 3);
        assert_eq!(result.0.usage.output_tokens, 2);
        assert_eq!(result.0.finish_reason, FinishReason::Stop);
    }

    #[tokio::test]
    async fn call_model_inner_invoke_error_maps_to_model_payload() {
        let model = InvokeErrorModel;
        let err = call_model_inner(
            &model,
            "agent-1",
            ModelRequest::new(),
            CancellationToken::new(),
        )
        .await
        .expect_err("invoke() error must surface as Err");
        assert!(
            matches!(err, ErrorKindPayload::Model { .. }),
            "expected ErrorKindPayload::Model, got {err:?}"
        );
    }

    #[tokio::test]
    async fn call_model_inner_stream_error_maps_to_model_payload() {
        let model = ScriptedModel::new(vec![Err(ModelError::Transport("boom".to_owned()))]);
        let err = call_model_inner(
            &model,
            "agent-1",
            ModelRequest::new(),
            CancellationToken::new(),
        )
        .await
        .expect_err("a stream-level Err event must surface as Err");
        match err {
            ErrorKindPayload::Model { message } => assert!(message.contains("boom")),
            other => panic!("expected ErrorKindPayload::Model, got {other:?}"),
        }
    }

    // ---- invoke_tool_inner ----------------------------------------------

    struct EchoTool;

    #[async_trait::async_trait]
    impl Tool<()> for EchoTool {
        fn name(&self) -> &str {
            "echo"
        }
        fn description(&self) -> &str {
            "echoes its arguments back"
        }
        fn schema(&self) -> &serde_json::Value {
            static SCHEMA: OnceLock<serde_json::Value> = OnceLock::new();
            SCHEMA.get_or_init(|| json!({ "type": "object" }))
        }
        async fn invoke(
            &self,
            _ctx: &ToolContext<()>,
            args: serde_json::Value,
        ) -> Result<ToolOutput, ToolError> {
            Ok(ToolOutput::new(args))
        }
    }

    fn def_with_tools(tools: Vec<Arc<dyn Tool<()>>>) -> DurableAgentDef<()> {
        DurableAgentDef {
            name: "agent-1".to_owned(),
            instructions: Arc::new("system prompt".to_owned()),
            model: Arc::new(InvokeErrorModel),
            tools,
            plan: AgentPlan {
                tool_defs: Vec::new(),
                model_settings: ModelSettings::new(),
                output: None,
            },
        }
    }

    #[tokio::test]
    async fn invoke_tool_inner_echoes_args_round_trip() {
        let def = def_with_tools(vec![Arc::new(EchoTool)]);
        let run_ctx: RunContext<()> = RunContext::ephemeral(());
        let call = ToolCallRequest {
            call_id: "c1".to_owned(),
            name: "echo".to_owned(),
            args: json!({"x": 1}),
        };

        let outcome = invoke_tool_inner(&def, &run_ctx, call).await;

        assert_eq!(outcome.call_id, "c1");
        let parts = outcome.result.expect("echo tool call must succeed");
        match &parts[0] {
            ContentPart::Text { text } => assert!(text.contains('1')),
            other => panic!("expected Text, got {other:?}"),
        }
    }

    #[tokio::test]
    async fn invoke_tool_inner_unknown_tool_is_err_outcome_not_panic() {
        let def = def_with_tools(vec![]);
        let run_ctx: RunContext<()> = RunContext::ephemeral(());
        let call = ToolCallRequest {
            call_id: "c1".to_owned(),
            name: "does-not-exist".to_owned(),
            args: json!({}),
        };

        let outcome = invoke_tool_inner(&def, &run_ctx, call).await;

        assert_eq!(outcome.call_id, "c1");
        let message = outcome
            .result
            .expect_err("unknown tool must be an Err outcome, not a panic");
        assert!(message.contains("unknown tool"));
    }

    // ---- render_instructions_inner ---------------------------------------

    #[tokio::test]
    async fn render_instructions_inner_delegates_to_instructions() {
        let def = def_with_tools(vec![]);
        let run_ctx: RunContext<()> = RunContext::ephemeral(());

        let text = render_instructions_inner(&def, &run_ctx).await;

        assert_eq!(text, "system prompt");
    }
}

//! Run-scoped context types.
//!
//! [`RunContext`] carries user data, session handle, hook registry, tracer,
//! and cancellation token across the agent loop.

use std::sync::Arc;

use crate::{
    ActionsHandle, AllowRule, ApprovalHandler, ApprovalOutcome, DenyRule, FailureSlot, Hook,
    PermissionDecision, PermissionMode, PermissionPolicy, RunConfig, Session, SessionState,
    ToolContext, ToolEffect,
};

/// Carries the per-run state shared across the agent loop, tools,
/// guardrails, and hooks.
///
/// `RunContext` does **not** implement `Default` — a context without a
/// session handle is meaningless. Construct via [`RunContext::new`].
///
/// # Example
///
/// ```
/// use std::sync::Arc;
/// use async_trait::async_trait;
/// use paigasus_helikon_core::{
///     CancellationToken, ConversationSnapshot, HookRegistry, RunContext,
///     SequenceId, Session, SessionError, SessionEvent, TracerHandle,
/// };
///
/// struct NoopSession;
/// #[async_trait]
/// impl Session for NoopSession {
///     async fn append(&self, _: &[SessionEvent]) -> Result<(), SessionError> { Ok(()) }
///     async fn events(&self, _: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
///         Ok(Vec::new())
///     }
///     async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
///         Ok(ConversationSnapshot::default())
///     }
/// }
///
/// let _ctx: RunContext<()> = RunContext::new(
///     Arc::new(()),
///     Arc::new(NoopSession),
///     HookRegistry::<()>::new(),
///     TracerHandle::default(),
///     CancellationToken::new(),
/// );
/// ```
pub struct RunContext<Ctx>
where
    Ctx: Send + Sync + 'static,
{
    user_ctx: Arc<Ctx>,
    session: Arc<dyn Session>,
    hooks: HookRegistry<Ctx>,
    tracer: TracerHandle,
    cancel: CancellationToken,
    /// Per-invocation execution policy, injected by a `Runner` (e.g.
    /// `TokioRunner`). This is the runner-injection channel, **not** general
    /// context state: it is deliberately NOT surfaced into [`ToolContext`] by
    /// [`RunContext::to_tool_context`]. `None` when an agent is run directly
    /// without a runner.
    run_config: Option<RunConfig>,
    /// Out-of-band carrier for the run's terminal structured [`crate::AgentError`].
    /// Written by [`crate::Agent::run`] at the moment of failure; read at the
    /// boundary by a [`crate::Runner`] / [`crate::RunResultStreaming`]. Like
    /// `run_config`, it is **not** projected into [`ToolContext`].
    failure: FailureSlot,
    /// Agent-nesting depth: 0 for a top-level run, incremented by
    /// [`RunContext::handoff_child`] and by `AgentAsTool` for each nested
    /// agent run. Bounded by [`crate::RunConfig::max_agent_depth`].
    agent_depth: u32,
    /// Run-scoped coordination KV shared across sub-agents (SMA-325). Shared by
    /// `subagent_child` / `handoff_child`; **not** projected as isolated.
    state: SessionState,
    /// Control side-channel a tool writes (e.g. `escalate`). A **fresh** handle
    /// per `subagent_child`, so a `LoopAgent` reads only the current sub-run's signal.
    actions: ActionsHandle,
    /// How the permission layer governs tool calls for this run.
    /// Monotonic on `Bypass`: once set, it cannot be downgraded.
    permission_mode: PermissionMode,
    /// Optional `canUseTool` policy, evaluated after deny rules and mode.
    permission_policy: Option<Arc<dyn PermissionPolicy<Ctx>>>,
    /// Deny rules evaluated before mode (override even `Bypass`).
    deny_rules: Vec<DenyRule>,
    /// Allow rules evaluated after deny+guard, before mode (positive
    /// short-circuit in any mode; the only path to Allow under `DontAsk`).
    allow_rules: Vec<AllowRule>,
    /// Resolves `AskUser` decisions; `None` → deny by default.
    approval_handler: Option<Arc<dyn ApprovalHandler>>,
    /// User-supplied guard rules, evaluated before mode (can Ask or Deny).
    guard_rules: Vec<crate::GuardRule>,
    /// Whether the always-on destructive default guards are consulted.
    default_guards: bool,
    /// Whether tool output is redacted before re-entering context.
    redact_output: bool,
    /// Extra secret values to redact, beyond the auto-sourced env set.
    extra_secrets: Vec<String>,
}

impl<Ctx> RunContext<Ctx>
where
    Ctx: Send + Sync + 'static,
{
    /// Construct a new [`RunContext`].
    pub fn new(
        user_ctx: Arc<Ctx>,
        session: Arc<dyn Session>,
        hooks: HookRegistry<Ctx>,
        tracer: TracerHandle,
        cancel: CancellationToken,
    ) -> Self {
        Self {
            user_ctx,
            session,
            hooks,
            tracer,
            cancel,
            run_config: None,
            failure: FailureSlot::new(),
            agent_depth: 0,
            state: SessionState::new(),
            actions: ActionsHandle::new(),
            permission_mode: PermissionMode::Default,
            permission_policy: None,
            deny_rules: Vec::new(),
            allow_rules: Vec::new(),
            approval_handler: None,
            guard_rules: Vec::new(),
            default_guards: true,
            redact_output: true,
            extra_secrets: Vec::new(),
        }
    }

    /// Zero-config context for the common ephemeral case: in-memory session,
    /// no hooks, default tracer, fresh cancellation token. Takes the user
    /// context **by value** and wraps it in an `Arc` internally, so the unit
    /// case is simply `RunContext::ephemeral(())`.
    ///
    /// # Example
    ///
    /// ```
    /// use paigasus_helikon_core::RunContext;
    ///
    /// let ctx: RunContext<()> = RunContext::ephemeral(());
    /// assert!(ctx.hooks().is_empty());
    /// ```
    pub fn ephemeral(user_ctx: Ctx) -> Self {
        Self::ephemeral_shared(Arc::new(user_ctx))
    }

    /// As [`RunContext::ephemeral`], but takes a pre-built `Arc<Ctx>` to
    /// **share** one user context across several ephemeral runs (e.g. a
    /// request-scoped server sharing an `Arc<AppCtx>`) without cloning it.
    ///
    /// # Example
    ///
    /// ```
    /// use std::sync::Arc;
    /// use paigasus_helikon_core::RunContext;
    ///
    /// struct AppCtx;
    /// let app = Arc::new(AppCtx);
    /// let _ctx = RunContext::ephemeral_shared(Arc::clone(&app));
    /// ```
    pub fn ephemeral_shared(user_ctx: Arc<Ctx>) -> Self {
        Self::new(
            user_ctx,
            Arc::new(crate::MemorySession::new()),
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
    }

    /// Replace the session handle. Pairs with [`RunContext::ephemeral`] to
    /// install a persistent session over the in-memory default.
    ///
    /// # Example
    ///
    /// ```
    /// use std::sync::Arc;
    /// use paigasus_helikon_core::{MemorySession, RunContext, TracerHandle};
    ///
    /// let _ctx: RunContext<()> = RunContext::ephemeral(())
    ///     .with_session(Arc::new(MemorySession::new()))
    ///     .with_tracer(TracerHandle::builder().with_session_id("s").build());
    /// ```
    pub fn with_session(mut self, session: Arc<dyn Session>) -> Self {
        self.session = session;
        self
    }

    /// Replace the hook registry.
    pub fn with_hooks(mut self, hooks: HookRegistry<Ctx>) -> Self {
        self.hooks = hooks;
        self
    }

    /// Replace the tracer handle (e.g. a populated [`TracerHandle::builder`]).
    pub fn with_tracer(mut self, tracer: TracerHandle) -> Self {
        self.tracer = tracer;
        self
    }

    /// Replace the cancellation token (e.g. to share one across runs).
    ///
    /// Intended for the builder chain on a freshly constructed context. It
    /// swaps the token wholesale and does **not** retroactively re-link any
    /// child tokens already derived via `handoff_child` / `subagent_child` /
    /// `to_tool_context` — so it is not a mid-run cancel swap.
    pub fn with_cancel(mut self, cancel: CancellationToken) -> Self {
        self.cancel = cancel;
        self
    }

    /// Borrow the user context.
    pub fn user_ctx(&self) -> &Arc<Ctx> {
        &self.user_ctx
    }
    /// Borrow the session handle.
    pub fn session(&self) -> &Arc<dyn Session> {
        &self.session
    }
    /// Borrow the hook registry.
    pub fn hooks(&self) -> &HookRegistry<Ctx> {
        &self.hooks
    }
    /// Borrow the tracer handle.
    pub fn tracer(&self) -> &TracerHandle {
        &self.tracer
    }
    /// Borrow the cancellation token.
    pub fn cancel(&self) -> &CancellationToken {
        &self.cancel
    }

    /// Borrow the run-scoped [`SessionState`] shared across sub-agents.
    pub fn state(&self) -> &SessionState {
        &self.state
    }
    /// Borrow the [`ActionsHandle`] for this (sub-)run.
    pub fn actions(&self) -> &ActionsHandle {
        &self.actions
    }

    /// Borrow the per-invocation [`RunConfig`], if a runner installed one.
    pub fn run_config(&self) -> Option<&RunConfig> {
        self.run_config.as_ref()
    }

    /// Clone the handle to this run's [`FailureSlot`].
    ///
    /// A [`crate::Runner`] clones this **before** moving the context into
    /// [`crate::Agent::run`] (the same way it clones `cancel` / `session`), then
    /// reads the structured error after the run's event stream drains.
    pub fn failure_handle(&self) -> FailureSlot {
        self.failure.clone()
    }

    /// Nesting depth that produced this context (0 at top level).
    pub fn agent_depth(&self) -> u32 {
        self.agent_depth
    }

    /// Stamp an explicit nesting depth. Used by `AgentAsTool` when it builds
    /// the isolated sub-context for its wrapped agent.
    pub fn with_agent_depth(mut self, depth: u32) -> Self {
        self.agent_depth = depth;
        self
    }

    /// Install the run-scoped [`SessionState`]. Used by `AgentAsTool` to build
    /// the fire-only context for `OnSubagentStop` so hooks observe the parent's
    /// shared `state` rather than a fresh one.
    pub(crate) fn with_state(mut self, state: SessionState) -> Self {
        self.state = state;
        self
    }

    /// A context for a handed-off sub-run. A handoff *continues the same
    /// logical run*, so the child **shares** session, hooks, cancel token,
    /// failure slot, and run config (including per-invocation limits like
    /// `max_turns` / `timeout`) — with `agent_depth` incremented by one.
    /// (Distinct from `AgentAsTool`, which builds an isolated context.)
    ///
    /// The increment saturates: depth is bounded far below `u32::MAX` by the
    /// driver's `max_agent_depth` guard, so saturating is purely defensive.
    pub fn handoff_child(&self) -> Self {
        Self {
            user_ctx: Arc::clone(&self.user_ctx),
            session: Arc::clone(&self.session),
            hooks: self.hooks.clone(),
            tracer: self.tracer.clone(),
            cancel: self.cancel.clone(),
            run_config: self.run_config.clone(),
            failure: self.failure.clone(),
            agent_depth: self.agent_depth.saturating_add(1),
            state: self.state.clone(),
            actions: self.actions.clone(),
            permission_mode: self.permission_mode,
            permission_policy: self.permission_policy.clone(),
            deny_rules: self.deny_rules.clone(),
            allow_rules: self.allow_rules.clone(),
            approval_handler: self.approval_handler.clone(),
            guard_rules: self.guard_rules.clone(),
            default_guards: self.default_guards,
            redact_output: self.redact_output,
            extra_secrets: self.extra_secrets.clone(),
        }
    }

    /// A context for one sub-agent of a workflow agent (`SequentialAgent`,
    /// `ParallelAgent`, `LoopAgent`). **Shares** the run-scoped `state`, session,
    /// cancel token, tracer, user context, and run config; gets a **fresh**
    /// `FailureSlot` and a **fresh** `ActionsHandle` (so the workflow agent reads
    /// only this sub-run's failure / escalate); `agent_depth` incremented by one.
    pub fn subagent_child(&self) -> Self {
        Self {
            user_ctx: Arc::clone(&self.user_ctx),
            session: Arc::clone(&self.session),
            hooks: self.hooks.clone(),
            tracer: self.tracer.clone(),
            cancel: self.cancel.clone(),
            run_config: self.run_config.clone(),
            failure: FailureSlot::new(),
            agent_depth: self.agent_depth.saturating_add(1),
            state: self.state.clone(),
            actions: ActionsHandle::new(),
            permission_mode: self.permission_mode,
            permission_policy: self.permission_policy.clone(),
            deny_rules: self.deny_rules.clone(),
            allow_rules: self.allow_rules.clone(),
            approval_handler: self.approval_handler.clone(),
            guard_rules: self.guard_rules.clone(),
            default_guards: self.default_guards,
            redact_output: self.redact_output,
            extra_secrets: self.extra_secrets.clone(),
        }
    }

    /// Install the per-invocation [`RunConfig`] (consuming builder). A
    /// [`crate::Runner`] calls this before [`crate::Agent::run`].
    pub fn with_run_config(mut self, config: RunConfig) -> Self {
        self.run_config = Some(config);
        self
    }

    /// Set the permission mode — **tighten-only**. Loosening is refused:
    /// `DontAsk` is terminal (no transition off it), and `Bypass` may only
    /// tighten to `DontAsk`, never loosen. All other transitions apply.
    pub fn with_permission_mode(mut self, mode: PermissionMode) -> Self {
        use PermissionMode::*;
        let allowed = match (self.permission_mode, mode) {
            (DontAsk, _) => false,
            (Bypass, DontAsk) => true,
            (Bypass, _) => false,
            _ => true,
        };
        if allowed {
            self.permission_mode = mode;
        }
        self
    }

    /// Install the run's permission policy (`canUseTool`).
    pub fn with_permission_policy(mut self, policy: Arc<dyn PermissionPolicy<Ctx>>) -> Self {
        self.permission_policy = Some(policy);
        self
    }

    /// Install deny rules, evaluated before mode (override even `Bypass`).
    pub fn with_deny_rules(mut self, rules: Vec<DenyRule>) -> Self {
        self.deny_rules = rules;
        self
    }

    /// Install allow rules (positive short-circuit; see [`crate::AllowRule`]).
    pub fn with_allow_rules(mut self, rules: Vec<AllowRule>) -> Self {
        self.allow_rules = rules;
        self
    }

    /// Install the approval handler that resolves `AskUser` decisions.
    pub fn with_approval_handler(mut self, handler: Arc<dyn ApprovalHandler>) -> Self {
        self.approval_handler = Some(handler);
        self
    }

    /// The current permission mode.
    pub fn permission_mode(&self) -> PermissionMode {
        self.permission_mode
    }

    /// The run's permission policy, if installed.
    pub fn permission_policy(&self) -> Option<&Arc<dyn PermissionPolicy<Ctx>>> {
        self.permission_policy.as_ref()
    }

    /// The run's deny rules.
    pub fn deny_rules(&self) -> &[DenyRule] {
        &self.deny_rules
    }

    /// The run's allow rules.
    pub fn allow_rules(&self) -> &[AllowRule] {
        &self.allow_rules
    }

    /// The run's approval handler, if installed.
    pub fn approval_handler(&self) -> Option<&Arc<dyn ApprovalHandler>> {
        self.approval_handler.as_ref()
    }

    /// Install user guard rules (evaluated before mode; can Ask or Deny).
    pub fn with_guard_rules(mut self, rules: Vec<crate::GuardRule>) -> Self {
        self.guard_rules = rules;
        self
    }

    /// Disable the always-on built-in destructive guard set (power-user opt-out).
    pub fn without_default_guards(mut self) -> Self {
        self.default_guards = false;
        self
    }

    /// Disable automatic secret redaction of tool output.
    pub fn without_output_redaction(mut self) -> Self {
        self.redact_output = false;
        self
    }

    /// Add extra secret values to redact from tool output. Additive: chained
    /// calls accumulate (earlier secrets are never dropped).
    pub fn with_extra_secrets(mut self, secrets: Vec<String>) -> Self {
        self.extra_secrets.extend(secrets);
        self
    }

    /// The run's user guard rules.
    pub fn guard_rules(&self) -> &[crate::GuardRule] {
        &self.guard_rules
    }

    /// Whether built-in destructive guards are active.
    pub fn default_guards(&self) -> bool {
        self.default_guards
    }

    /// Whether tool-output redaction is active.
    pub fn redact_output(&self) -> bool {
        self.redact_output
    }

    /// Extra secret values to redact.
    pub fn extra_secrets(&self) -> &[String] {
        &self.extra_secrets
    }

    /// Authorize one tool call on its effective args: deny rules › guard
    /// rules › allow rules › mode › policy › approval handler (`AskUser`
    /// resolved here, default Deny). Extracted from the loop driver so a
    /// durable runner (e.g. a Temporal activity) can authorize a tool call
    /// with exactly the same pipeline the ephemeral agent loop applies
    /// inline, without needing a borrow of the loop's private control-layer
    /// type.
    pub async fn authorize_tool(
        &self,
        tool: &str,
        effect: ToolEffect,
        args: &serde_json::Value,
    ) -> PermissionDecision {
        // 1. Deny rules — absolute, override even Bypass.
        if self.deny_rules().iter().any(|r| r.matches(tool, args)) {
            return PermissionDecision::Deny {
                reason: format!("denied by deny rule: {tool}"),
            };
        }
        // 2. Guard rules — built-in destructive defaults (unless opted out)
        // then user guard rules. Run before mode, so they beat Bypass; may Ask.
        let builtin = if self.default_guards() {
            crate::GuardRule::destructive_defaults()
        } else {
            Vec::new()
        };
        for guard in builtin.iter().chain(self.guard_rules()) {
            if guard.matches(tool, args) {
                match guard.action() {
                    crate::GuardAction::Deny { reason } => {
                        return PermissionDecision::Deny {
                            reason: reason.clone(),
                        };
                    }
                    crate::GuardAction::Ask { prompt } => {
                        let Some(handler) = self.approval_handler() else {
                            return PermissionDecision::Deny {
                                reason: format!("destructive command requires approval: {prompt}"),
                            };
                        };
                        // Approval clears THIS guard only — continue the pipeline
                        // so later guards and the allow/mode/policy steps still
                        // apply. A matching allow rule may still short-circuit
                        // before mode/policy; approval itself is not a blanket
                        // authorization.
                        match handler.decide(tool, prompt, args).await {
                            ApprovalOutcome::Allow => continue,
                            ApprovalOutcome::Deny { reason } => {
                                return PermissionDecision::Deny { reason };
                            }
                        }
                    }
                }
            }
        }
        // 3. Allow rules — positive short-circuit in ANY mode (after deny+guard,
        // before mode). A global per-tool/per-command pre-approval that skips
        // the policy AND any mode restriction (including Plan's read-only gate).
        // Deny and guard already ran, so this cannot resurrect a denied/guarded
        // call.
        if self.allow_rules().iter().any(|r| r.matches(tool, args)) {
            return PermissionDecision::Allow;
        }
        // 4. Mode.
        match self.permission_mode() {
            PermissionMode::Bypass => return PermissionDecision::Allow,
            PermissionMode::Plan if effect != ToolEffect::ReadOnly => {
                return PermissionDecision::Deny {
                    reason: format!("Plan mode forbids the side-effecting tool `{tool}`"),
                };
            }
            PermissionMode::AcceptEdits if effect == ToolEffect::Write => {
                return PermissionDecision::Allow;
            }
            PermissionMode::DontAsk => {
                return PermissionDecision::Deny {
                    reason: format!("DontAsk mode: no allow rule matched `{tool}`"),
                };
            }
            _ => {}
        }
        // 5. Policy (canUseTool). None ⇒ permissive.
        let decision = match self.permission_policy() {
            None => return PermissionDecision::Allow,
            Some(policy) => policy.check(self, tool, args).await,
        };
        // 6. AskUser ⇒ approval handler; None ⇒ Deny.
        match decision {
            PermissionDecision::AskUser { prompt } => match self.approval_handler() {
                None => PermissionDecision::Deny {
                    reason: "no approval handler installed".to_owned(),
                },
                Some(handler) => match handler.decide(tool, &prompt, args).await {
                    ApprovalOutcome::Allow => PermissionDecision::Allow,
                    ApprovalOutcome::Deny { reason } => PermissionDecision::Deny { reason },
                },
            },
            other => other,
        }
    }

    /// Clone the permission/guard/redaction config into a [`crate::tool::PermissionFields`]
    /// bundle for projection into a [`ToolContext`].
    pub(crate) fn clone_permission_fields(&self) -> crate::tool::PermissionFields<Ctx> {
        crate::tool::PermissionFields {
            mode: self.permission_mode,
            policy: self.permission_policy.clone(),
            deny_rules: self.deny_rules.clone(),
            allow_rules: self.allow_rules.clone(),
            approval_handler: self.approval_handler.clone(),
            guard_rules: self.guard_rules.clone(),
            default_guards: self.default_guards,
            redact_output: self.redact_output,
            extra_secrets: self.extra_secrets.clone(),
        }
    }

    /// Project the narrower [`ToolContext`] from this [`RunContext`].
    ///
    /// Tools receive `user_ctx`, `tracer`, and a **child** cancellation
    /// token. The child observes the parent's cancellation but tool-side
    /// `cancel()` calls only cancel the tool's subtree — they do not
    /// propagate back to the run.
    ///
    /// Tools do not see the session handle (the runner owns persistence). The
    /// run-level hook registry is projected as a `pub(crate)` carrier (for
    /// `agent_as_tool` to fire `OnSubagentStop`), but is not exposed to `Tool`
    /// impls — hooks fire around tool invocations, not from inside.
    pub fn to_tool_context(&self) -> ToolContext<Ctx> {
        let max_agent_depth = self
            .run_config
            .as_ref()
            .map(|c| c.max_agent_depth)
            .unwrap_or_else(|| RunConfig::default().max_agent_depth);
        ToolContext::new(
            Arc::clone(&self.user_ctx),
            self.tracer.clone(),
            self.cancel.child_token(),
            self.agent_depth,
            max_agent_depth,
        )
        .with_state(self.state.clone())
        .with_actions(self.actions.clone())
        .with_hooks(self.hooks.clone())
        .with_permissions(self.clone_permission_fields())
    }
}

#[cfg(test)]
mod runcontext_tests {
    use super::*;
    use crate::{MemorySession, RunConfig};
    use std::sync::Arc;

    #[test]
    fn failure_handle_shares_the_context_slot() {
        use crate::AgentError;
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            crate::HookRegistry::new(),
            crate::TracerHandle::default(),
            crate::CancellationToken::new(),
        );
        let handle = ctx.failure_handle();
        handle.set(AgentError::MaxTurnsExceeded(2));
        // A second handle from the same ctx observes the write.
        assert!(matches!(
            ctx.failure_handle().take(),
            Some(AgentError::MaxTurnsExceeded(2))
        ));
    }

    #[test]
    fn tracer_handle_builder_roundtrips_and_default_is_empty() {
        let empty = TracerHandle::default();
        assert!(empty.session_id().is_none());
        assert!(empty.user_id().is_none());
        assert!(empty.tags().is_empty());

        let h = TracerHandle::builder()
            .with_session_id("sess-1")
            .with_user_id("user-1")
            .with_tag("prod")
            .with_tag("beta")
            .build();
        assert_eq!(h.session_id(), Some("sess-1"));
        assert_eq!(h.user_id(), Some("user-1"));
        assert_eq!(h.tags(), &["prod", "beta"]);
    }

    #[test]
    fn with_run_config_round_trips_and_defaults_none() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        );
        assert!(ctx.run_config().is_none());

        let ctx =
            ctx.with_run_config(RunConfig::new().with_timeout(std::time::Duration::from_secs(1)));
        assert_eq!(
            ctx.run_config().unwrap().timeout,
            Some(std::time::Duration::from_secs(1))
        );
    }

    #[test]
    fn handoff_child_increments_depth_and_shares_failure_slot() {
        use crate::AgentError;
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        );
        assert_eq!(ctx.agent_depth(), 0);

        let child = ctx.handoff_child();
        assert_eq!(child.agent_depth(), 1);
        assert_eq!(child.handoff_child().agent_depth(), 2);

        // The child shares the parent's failure slot (so a failing target
        // reaches the parent's boundary).
        child.failure_handle().set(AgentError::MaxTurnsExceeded(2));
        assert!(matches!(
            ctx.failure_handle().take(),
            Some(AgentError::MaxTurnsExceeded(2))
        ));
    }

    #[test]
    fn with_agent_depth_sets_depth() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .with_agent_depth(5);
        assert_eq!(ctx.agent_depth(), 5);
    }

    #[test]
    fn to_tool_context_projects_depth_and_max() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .with_agent_depth(2)
        .with_run_config(RunConfig::new().with_max_agent_depth(5));

        let tc = ctx.to_tool_context();
        assert_eq!(tc.agent_depth(), 2);
        assert_eq!(tc.max_agent_depth(), 5);
    }

    #[test]
    fn to_tool_context_projects_state_and_actions() {
        use serde_json::json;
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        );
        ctx.state().set("k", "v");
        let tc = ctx.to_tool_context();
        assert_eq!(tc.state().get("k"), Some(json!("v")));
        tc.actions().escalate();
        assert!(
            ctx.actions().is_escalated(),
            "tool escalate reaches the run"
        );
    }

    #[test]
    fn permission_mode_defaults_to_default_and_setter_round_trips() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        );
        assert_eq!(ctx.permission_mode(), crate::PermissionMode::Default);
        let ctx = ctx.with_permission_mode(crate::PermissionMode::Plan);
        assert_eq!(ctx.permission_mode(), crate::PermissionMode::Plan);
    }

    #[test]
    fn bypass_cannot_be_downgraded() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .with_permission_mode(crate::PermissionMode::Bypass)
        .with_permission_mode(crate::PermissionMode::Plan); // no-op
        assert_eq!(ctx.permission_mode(), crate::PermissionMode::Bypass);
    }

    #[test]
    fn permission_mode_is_tighten_only() {
        use crate::PermissionMode::*;
        let base = || {
            RunContext::new(
                Arc::new(()),
                Arc::new(MemorySession::new()) as Arc<dyn Session>,
                HookRegistry::new(),
                TracerHandle::default(),
                CancellationToken::new(),
            )
        };
        // Bypass can tighten to DontAsk …
        assert_eq!(
            base()
                .with_permission_mode(Bypass)
                .with_permission_mode(DontAsk)
                .permission_mode(),
            DontAsk
        );
        // … but cannot loosen to Default/Plan.
        assert_eq!(
            base()
                .with_permission_mode(Bypass)
                .with_permission_mode(Default)
                .permission_mode(),
            Bypass
        );
        // DontAsk is terminal — no transition off it.
        assert_eq!(
            base()
                .with_permission_mode(DontAsk)
                .with_permission_mode(Bypass)
                .permission_mode(),
            DontAsk
        );
        assert_eq!(
            base()
                .with_permission_mode(DontAsk)
                .with_permission_mode(Default)
                .permission_mode(),
            DontAsk
        );
        // Normal modes still settable.
        assert_eq!(base().with_permission_mode(Plan).permission_mode(), Plan);
    }

    #[test]
    fn handoff_child_inherits_mode_and_keeps_bypass_sticky() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .with_permission_mode(crate::PermissionMode::Bypass);
        assert_eq!(
            ctx.handoff_child().permission_mode(),
            crate::PermissionMode::Bypass
        );
        assert_eq!(
            ctx.subagent_child().permission_mode(),
            crate::PermissionMode::Bypass
        );
    }

    #[test]
    fn to_tool_context_projects_permission_mode() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .with_permission_mode(crate::PermissionMode::Bypass);
        assert_eq!(
            ctx.to_tool_context().permission_mode(),
            crate::PermissionMode::Bypass
        );
    }

    #[test]
    fn guard_rules_default_on_and_inherit_through_children() {
        use crate::{GuardRule, PermissionMode};
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .with_permission_mode(PermissionMode::Bypass)
        .with_guard_rules(vec![GuardRule::destructive_defaults().remove(0)]);

        assert!(ctx.default_guards());
        assert_eq!(ctx.guard_rules().len(), 1);
        assert_eq!(ctx.handoff_child().guard_rules().len(), 1);
        assert_eq!(ctx.subagent_child().guard_rules().len(), 1);
        assert_eq!(ctx.to_tool_context().guard_rules().len(), 1);
        assert!(ctx.handoff_child().default_guards());
    }

    #[test]
    fn allow_rules_inherit_through_children() {
        use crate::AllowRule;
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .with_allow_rules(vec![AllowRule::tool("WebSearch")]);
        assert_eq!(ctx.allow_rules().len(), 1);
        assert_eq!(ctx.handoff_child().allow_rules().len(), 1);
        assert_eq!(ctx.subagent_child().allow_rules().len(), 1);
        // copy-site #3: the PermissionFields projection consumed by to_tool_context.
        // clone_permission_fields is pub(crate) and PermissionFields.allow_rules is
        // pub(crate), both reachable from this in-crate test module.
        assert_eq!(ctx.clone_permission_fields().allow_rules.len(), 1);
    }

    #[test]
    fn without_default_guards_disables_builtins() {
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        )
        .without_default_guards();
        assert!(!ctx.default_guards());
        assert!(!ctx.subagent_child().default_guards());
    }

    #[test]
    fn subagent_child_shares_state_fresh_actions_increments_depth() {
        use serde_json::json;
        let ctx: RunContext<()> = RunContext::new(
            Arc::new(()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::default(),
            CancellationToken::new(),
        );
        ctx.state().set("k", "v");
        ctx.actions().escalate();

        let child = ctx.subagent_child();
        assert_eq!(child.agent_depth(), 1);
        assert_eq!(child.state().get("k"), Some(json!("v")), "state is shared");
        assert!(!child.actions().is_escalated(), "actions slot is fresh");

        child.state().set("k2", "v2");
        assert_eq!(ctx.state().get("k2"), Some(json!("v2")), "shared store");

        use crate::AgentError;
        child.failure_handle().set(AgentError::MaxTurnsExceeded(1));
        assert!(ctx.failure_handle().take().is_none(), "fresh failure slot");
    }

    #[test]
    fn ephemeral_matches_new_defaults() {
        let ctx: RunContext<()> = RunContext::ephemeral(());
        assert_eq!(ctx.agent_depth(), 0);
        assert_eq!(ctx.permission_mode(), crate::PermissionMode::Default);
        assert!(ctx.default_guards());
        assert!(ctx.redact_output());
        assert!(ctx.run_config().is_none());
        assert!(ctx.hooks().is_empty());
        assert!(ctx.deny_rules().is_empty());
        assert!(ctx.allow_rules().is_empty());
    }

    #[test]
    fn ephemeral_shared_keeps_inner_ctx_type() {
        struct Marker;
        let ctx: RunContext<Marker> = RunContext::ephemeral_shared(Arc::new(Marker));
        // Compile-time proof that Ctx == Marker, not Arc<Marker>: user_ctx()
        // returns &Arc<Marker>, so .as_ref() yields &Marker.
        let _inner: &Marker = ctx.user_ctx().as_ref();
    }

    #[test]
    fn with_session_swaps_handle() {
        let session: Arc<dyn Session> = Arc::new(MemorySession::new());
        let ctx: RunContext<()> = RunContext::ephemeral(()).with_session(Arc::clone(&session));
        assert!(Arc::ptr_eq(ctx.session(), &session));
    }

    #[test]
    fn with_hooks_installs_registry() {
        struct NoopHook;
        #[async_trait::async_trait]
        impl crate::Hook<()> for NoopHook {
            async fn on_event(
                &self,
                _ctx: &RunContext<()>,
                _event: &crate::HookEvent,
            ) -> crate::HookDecision {
                crate::HookDecision::Allow
            }
        }
        let mut registry = HookRegistry::<()>::new();
        registry.push(Arc::new(NoopHook));
        let ctx: RunContext<()> = RunContext::ephemeral(()).with_hooks(registry);
        assert!(!ctx.hooks().is_empty());
    }

    #[test]
    fn with_tracer_round_trips() {
        let ctx: RunContext<()> = RunContext::ephemeral(())
            .with_tracer(TracerHandle::builder().with_session_id("sess-1").build());
        assert_eq!(ctx.tracer().session_id(), Some("sess-1"));
    }

    #[test]
    fn with_cancel_token_cancels() {
        let token = CancellationToken::new();
        let ctx: RunContext<()> = RunContext::ephemeral(()).with_cancel(token.clone());
        assert!(!ctx.cancel().is_cancelled());
        token.cancel();
        assert!(ctx.cancel().is_cancelled());
    }
}

/// Re-export of [`tokio_util::sync::CancellationToken`] so downstream
/// crates need not depend on `tokio-util` directly.
pub use tokio_util::sync::CancellationToken;

/// Registry of hooks active for one run.
///
/// Today the surface is intentionally minimal — just `new`, `push`,
/// `iter`, and `is_empty`. The agent-loop ticket grows this when it
/// needs per-event filtering.
pub struct HookRegistry<Ctx>
where
    Ctx: Send + Sync + 'static,
{
    hooks: Vec<Arc<dyn Hook<Ctx>>>,
}

impl<Ctx> HookRegistry<Ctx>
where
    Ctx: Send + Sync + 'static,
{
    /// Construct an empty registry.
    pub fn new() -> Self {
        Self { hooks: Vec::new() }
    }

    /// Register a hook.
    pub fn push(&mut self, hook: Arc<dyn Hook<Ctx>>) {
        self.hooks.push(hook);
    }

    /// Iterate over registered hooks in registration order.
    pub fn iter(&self) -> impl Iterator<Item = &Arc<dyn Hook<Ctx>>> {
        self.hooks.iter()
    }

    /// `true` if no hooks are registered.
    pub fn is_empty(&self) -> bool {
        self.hooks.is_empty()
    }
}

impl<Ctx> Default for HookRegistry<Ctx>
where
    Ctx: Send + Sync + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<Ctx> Clone for HookRegistry<Ctx>
where
    Ctx: Send + Sync + 'static,
{
    fn clone(&self) -> Self {
        Self {
            hooks: self.hooks.clone(),
        }
    }
}

/// Carrier for per-run trace-level attributes (Langfuse `session.id` /
/// `user.id` / `tags`) that the agent loop stamps onto the run and turn
/// spans. Construct an empty handle with [`TracerHandle::default`] or a
/// populated one via [`TracerHandle::builder`].
#[derive(Debug, Clone, Default)]
pub struct TracerHandle {
    session_id: Option<String>,
    user_id: Option<String>,
    tags: Vec<String>,
}

impl TracerHandle {
    /// Start building a populated handle.
    pub fn builder() -> TracerHandleBuilder {
        TracerHandleBuilder::default()
    }

    /// Langfuse session id, if set.
    pub fn session_id(&self) -> Option<&str> {
        self.session_id.as_deref()
    }

    /// Langfuse user id, if set.
    pub fn user_id(&self) -> Option<&str> {
        self.user_id.as_deref()
    }

    /// Langfuse trace tags (possibly empty).
    pub fn tags(&self) -> &[String] {
        &self.tags
    }
}

/// Consuming builder for [`TracerHandle`].
#[derive(Debug, Default)]
pub struct TracerHandleBuilder {
    session_id: Option<String>,
    user_id: Option<String>,
    tags: Vec<String>,
}

impl TracerHandleBuilder {
    /// Set the Langfuse session id.
    pub fn with_session_id(mut self, id: impl Into<String>) -> Self {
        self.session_id = Some(id.into());
        self
    }

    /// Set the Langfuse user id.
    pub fn with_user_id(mut self, id: impl Into<String>) -> Self {
        self.user_id = Some(id.into());
        self
    }

    /// Append one Langfuse trace tag.
    pub fn with_tag(mut self, tag: impl Into<String>) -> Self {
        self.tags.push(tag.into());
        self
    }

    /// Finish building the [`TracerHandle`].
    pub fn build(self) -> TracerHandle {
        TracerHandle {
            session_id: self.session_id,
            user_id: self.user_id,
            tags: self.tags,
        }
    }
}

//! Temporal-backed durable runtime for the Paigasus Helikon AI SDK.
//!
//! A [`Runner`](paigasus_helikon_core::Runner) implementation that makes agent runs durable through
//! [Temporal](https://temporal.io). Each run becomes a workflow, each model invocation and tool call
//! becomes an activity, and the agent loop is reconstructed via deterministic replay of the
//! workflow's history. A crash mid-run resumes from the last completed activity, recovering events
//! and run state automatically.
//!
//! # Quick start
//!
//! Start a local dev server:
//!
//! ```bash
//! temporal server start-dev
//! ```
//!
//! Start a worker that registers your agent and serves its activities on a
//! task queue (`NullModel` stands in for any [`Model`](paigasus_helikon_core::Model)
//! impl — e.g. an OpenAI/Anthropic provider crate's model):
//!
//! ```no_run
//! # struct NullModel;
//! # #[async_trait::async_trait]
//! # impl paigasus_helikon_core::Model for NullModel {
//! #     async fn invoke(
//! #         &self,
//! #         _request: paigasus_helikon_core::ModelRequest,
//! #         _cancel: paigasus_helikon_core::CancellationToken,
//! #     ) -> Result<
//! #         futures_core::stream::BoxStream<
//! #             'static,
//! #             Result<paigasus_helikon_core::ModelEvent, paigasus_helikon_core::ModelError>,
//! #         >,
//! #         paigasus_helikon_core::ModelError,
//! #     > {
//! #         let events: Vec<
//! #             Result<paigasus_helikon_core::ModelEvent, paigasus_helikon_core::ModelError>,
//! #         > = vec![];
//! #         Ok(Box::pin(futures_util::stream::iter(events)))
//! #     }
//! #     fn capabilities(&self) -> paigasus_helikon_core::ModelCapabilities {
//! #         paigasus_helikon_core::ModelCapabilities::default()
//! #     }
//! # }
//! use std::sync::Arc;
//!
//! use paigasus_helikon_core::LlmAgent;
//! use paigasus_helikon_runtime_temporal::worker::TemporalAgentWorker;
//! use temporalio_client::{Client, ClientOptions, Connection, ConnectionOptions};
//!
//! #[tokio::main]
//! async fn main() -> Result<(), Box<dyn std::error::Error>> {
//!     // Connect to the Temporal server (`temporal server start-dev` locally).
//!     let target = url::Url::parse("http://localhost:7233")?;
//!     let connection = Connection::connect(ConnectionOptions::new(target).build()).await?;
//!     let client = Client::new(connection, ClientOptions::new("default").build())?;
//!
//!     let agent = Arc::new(
//!         LlmAgent::builder::<()>()
//!             .name("assistant")
//!             .model(NullModel)
//!             .build(),
//!     );
//!
//!     // Registration fails fast if the agent uses hooks, guardrails, or
//!     // handoffs (unsupported in v0 — see below). Serves until shutdown.
//!     TemporalAgentWorker::builder::<()>()
//!         .task_queue("helikon-agents")
//!         .client(client)
//!         .with_ctx(|| ())
//!         .register(agent)?
//!         .build()?
//!         .run()
//!         .await?;
//!     Ok(())
//! }
//! ```
//!
//! Then, from any client process, run the agent durably through
//! [`runner::TemporalRunner`] — the run executes on the worker serving the
//! task queue; client-side, the runner needs the agent definition only for
//! its name and session semantics:
//!
//! ```no_run
//! # struct NullModel;
//! # #[async_trait::async_trait]
//! # impl paigasus_helikon_core::Model for NullModel {
//! #     async fn invoke(
//! #         &self,
//! #         _request: paigasus_helikon_core::ModelRequest,
//! #         _cancel: paigasus_helikon_core::CancellationToken,
//! #     ) -> Result<
//! #         futures_core::stream::BoxStream<
//! #             'static,
//! #             Result<paigasus_helikon_core::ModelEvent, paigasus_helikon_core::ModelError>,
//! #         >,
//! #         paigasus_helikon_core::ModelError,
//! #     > {
//! #         let events: Vec<
//! #             Result<paigasus_helikon_core::ModelEvent, paigasus_helikon_core::ModelError>,
//! #         > = vec![];
//! #         Ok(Box::pin(futures_util::stream::iter(events)))
//! #     }
//! #     fn capabilities(&self) -> paigasus_helikon_core::ModelCapabilities {
//! #         paigasus_helikon_core::ModelCapabilities::default()
//! #     }
//! # }
//! use paigasus_helikon_core::{AgentInput, LlmAgent, RunConfig, RunContext, Runner};
//! use paigasus_helikon_runtime_temporal::runner::{TemporalRunner, TemporalRunnerConfig};
//! use temporalio_client::{Client, ClientOptions, Connection, ConnectionOptions};
//!
//! #[tokio::main]
//! async fn main() -> Result<(), Box<dyn std::error::Error>> {
//!     let target = url::Url::parse("http://localhost:7233")?;
//!     let connection = Connection::connect(ConnectionOptions::new(target).build()).await?;
//!     let client = Client::new(connection, ClientOptions::new("default").build())?;
//!
//!     let agent = LlmAgent::builder::<()>()
//!         .name("assistant")
//!         .model(NullModel)
//!         .build();
//!
//!     let runner = TemporalRunner::new(client, TemporalRunnerConfig::new("helikon-agents"));
//!     let result = runner
//!         .run(
//!             &agent,
//!             RunContext::ephemeral(()),
//!             AgentInput::from_user_text("Hello!"),
//!             RunConfig::default(),
//!         )
//!         .await?;
//!     println!("{}", result.final_output);
//!     Ok(())
//! }
//! ```
//!
//! # v0 Constraint Set
//!
//! The durable Temporal runtime v0 explicitly does not support:
//!
//! - **Hooks** (`on_turn_started`, `on_model_response`, etc.) — arbitrary async code cannot be
//!   made deterministic inside the workflow. Running hooks in activities is deferred past v0.
//! - **Handoffs** (`NextAction::Handoff`) — the agent loop cannot hand off to another system while
//!   remaining durable. Handoffs are rejected at registration time with a descriptive error.
//! - **Guardrails** (input/output validation) — running guardrail logic inside the deterministic
//!   workflow is not yet supported. Guardrails are rejected at registration time.
//! - **Nested agents** (agent-as-tool) — while the tool call executes and completes, the nested
//!   agent's run is opaque to Temporal's durability (not itself durable). The nested run may
//!   complete but the outer run sees it as a black-box activity result, not as a durable workflow.
//!
//! The first three — hooks, handoffs, and (input/output) guardrails — are detected during agent
//! registration (via [`worker::TemporalAgentWorkerBuilder::register`]) and rejected with a
//! descriptive [`worker::RegistrationError`], failing fast rather than silently skipping
//! unsupported features. Nested agent-as-tool runs are **permitted** — registration succeeds —
//! but the nested run executes non-durably inside its tool activity: a crash-retry of that
//! activity re-executes the entire nested run from scratch.
//!
//! # Worker-Side Posture and Security Boundary
//!
//! The agent's [`RunContext`](paigasus_helikon_core::RunContext) (`Ctx` generic type) is not
//! serializable and does not cross the client→worker boundary. For every tool-call activity, the
//! **worker fabricates a fresh `RunContext::ephemeral(ctx).with_cancel(...)`** from its configured
//! context factory. v0 ships this with **fixed, non-configurable defaults**:
//!
//! - `redact_output = true` — tool output is redacted before it re-enters the conversation, using
//!   secrets sourced from the worker process's own environment (`_API_KEY`/`_TOKEN`/`_SECRET`/
//!   `_PASSWORD`/`_CREDENTIAL`-suffixed variables) plus an empty `extra_secrets` list.
//! - [`PermissionMode::Default`](paigasus_helikon_core::PermissionMode) with no `permission_policy`
//!   installed — permissive by default, except for the always-on built-in destructive guards
//!   (blocking `rm -rf /`/`~`, writes under protected system paths, and writes touching
//!   `.git`/`.ssh`/`.env*`).
//! - No `approval_handler` installed — a destructive guard's `Ask` therefore **degrades to
//!   `Deny`**, since nothing is registered to resolve it.
//! - No deny rules, no allow rules, no custom guard rules — the caller cannot install any of
//!   these on the durable path.
//!
//! **None of the caller's `RunContext` configuration propagates to the worker.** Specifically,
//! the following caller-side fields never cross the client→worker boundary: deny/allow rules, the
//! permission mode and policy, the approval handler, and `extra_secrets`. The worker's fixed v0
//! defaults above are authoritative for every tool call executed in the activity, regardless of
//! what the caller configured on its own `RunContext`.
//!
//! **Temporal history is a persistence boundary.** Tool outputs are redacted *before* they are
//! recorded in the workflow history (Temporal's durable storage), per the fixed `redact_output =
//! true` default above. Treat Temporal history as a permanent external record.
//!
//! Worker-side posture configuration — letting a worker operator configure permission mode,
//! deny/allow rules, an approval handler, or `extra_secrets` for its fabricated `RunContext` — is
//! future work, alongside the serializable-`Ctx`-seed mechanism for finer-grained permission
//! inheritance.
//!
//! # Retry Semantics and Tool Idempotency
//!
//! ## Model errors
//!
//! Per [ADR-10](https://smk1085.github.io/paigasus-helikon/contributing/adrs.html), the runtime
//! never retries model errors (`ModelError` variants). Model failures are **non-retryable** at the
//! activity level and cause the run to fail with [`RunError::Agent(...)`](paigasus_helikon_core::RunError)
//! carrying the provider's error message as a plain string. This differs from `TokioRunner`: the
//! typed `AgentError::Model` variant is **not** reconstructed across the durable boundary — the
//! activity failure payload carries only the message, not the original `ModelError`'s structure.
//!
//! If your application needs model retries, wrap your model in `RetryingModel` (from
//! [`paigasus_helikon_runtime_tokio`](https://docs.rs/paigasus-helikon-runtime-tokio)) before
//! registering it with the worker. That's the sanctioned retry path — retries are an
//! application-layer concern, not a runtime concern.
//!
//! ## Tool errors
//!
//! Tool-level errors never fail the activity: they return as part of the
//! [`ToolCallOutcome`](paigasus_helikon_core::ToolCallOutcome) and are fed back to the model as
//! data (the model can see what went wrong and adapt). Only infrastructure-level panics fail the
//! activity attempt.
//!
//! ## Crash-retry vs error-retry
//!
//! The `model_retry_policy` and `tool_retry_policy` on the worker builder control **crash
//! recovery**, not application-level retries:
//!
//! - **Crash recovery**: If the activity worker crashes or times out mid-execution, Temporal
//!   retries the activity on a live worker. The workflow replays its history deterministically,
//!   returns the recorded result for activities that completed, and retries only the in-flight
//!   activity. This is the crash-resume acceptance criterion.
//! - **Application-level errors**: These are marked non-retryable at the activity level (per
//!   ADR-10 for models, or returned as outcomes for tools) and do not trigger retries.
//!
//! **Tool idempotency under crash-retry:** Because a crashed tool activity retries on a live
//! worker, **tool authors must implement idempotency** if a tool call cannot safely run twice.
//! Set `max_attempts: 1` on the tool's retry policy to opt out of crash-recovery (the run fails
//! instead of resuming), accepting the trade-off: the run is no longer durable against crashes
//! mid-tool-call.
//!
//! # Payload Budget and Conversation Size
//!
//! The durable driver builds every `ModelRequest` from the **full conversation** — including all
//! history since the run started. This means each `call_model` activity payload includes the
//! entire conversation-so-far, causing payload size to grow quadratically with the number of turns.
//! Temporal's default gRPC payload limit is ~2–4 MB, with server-side warnings around 512 KB.
//!
//! **Practical budget for v0:** A single activity payload should stay under **~1.5 MB of JSON**.
//! This typically allows **15–20 turns** with tool outputs averaging **≤50 KB each**. A single
//! tool result larger than ~1.5 MB will fail its activity outright.
//!
//! **Strategies to fit within the budget:**
//! - Bound tool output size via the tool implementation (e.g., truncate summaries, paginate results).
//! - Limit `max_turns` in [`RunConfig`](paigasus_helikon_core::RunConfig) to stay within the turn budget.
//! - Monitor your actual payload sizes in Temporal's Web UI to verify your use case fits.
//!
//! Payload codecs (custom serialization), claim-check blob offloading, and conversation
//! compaction are named follow-up work, not silent gaps.
//!
//! # Upgrade Discipline and Determinism
//!
//! The workflow's deterministic core is [`paigasus_helikon_core::loop_state::transition`], which
//! lives in a separately versioned crate. Replaying an in-flight workflow against a worker with a
//! **different version of `paigasus-helikon-core` or `paigasus-helikon-runtime-temporal`** can
//! cause non-determinism errors (the workflow's replayed decisions don't match the new code's
//! logic).
//!
//! **Operational guidance for v0 (machinery deferred to a future release):**
//!
//! 1. **Drain in-flight runs before redeploying.** Agent runs are typically minutes-to-hours, not
//!    months. Before deploying a new worker version with a bumped core/temporal crate:
//!    - Wait for existing workflows to complete, or
//!    - Use blue-green task queues: point the old worker to `"queue-v1"` and the runner to
//!      `"queue-v2"`, run new workflows on v2 while old ones drain from v1, then decommission v1.
//! 2. **Check the CHANGELOG.** Any release of this crate whose transition behavior changed is
//!    flagged as replay-breaking.
//! 3. **Production path:** [Temporal Worker Versioning (Build IDs)](https://docs.temporal.io/workers#worker-versioning)
//!    is the long-term solution for zero-downtime updates; support is pending in the Rust SDK.
//!
//! # Links
//!
//! - [API reference (docs.rs)](https://docs.rs/paigasus-helikon-runtime-temporal)
//! - [Guide & concepts](https://smk1085.github.io/paigasus-helikon/) — see [Runtimes](https://smk1085.github.io/paigasus-helikon/concepts/runtimes.html)
//! - [Temporal documentation](https://docs.temporal.io)
//! - [Source & issues](https://github.com/SMK1085/paigasus-helikon)

/// Thin Temporal activity layer over the SDK-free driver-facing inner
/// functions, plus the process-local per-agent registry a durable worker
/// resolves by name (never serialized — see [`driver::AgentPlan`]'s docs on
/// why). Private: every externally-relevant type it defines is re-exported
/// or consumed through [`worker`].
mod activities;
/// The pure durable-loop step machine.
///
/// [`driver::DurableDriver`] wraps [`paigasus_helikon_core::transition`] with
/// the bookkeeping (conversation, accumulated events, cumulative usage) a
/// Temporal workflow needs to drive an agent run one activity result at a
/// time, without any Temporal SDK dependency of its own.
pub mod driver;
/// Error types for the Temporal-backed durable runtime.
pub mod error;
/// Wire-format payload types exchanged between the Temporal workflow and its
/// activities.
pub mod payloads;
/// The client-side [`paigasus_helikon_core::Runner`] implementation:
/// [`runner::TemporalRunner`] starts the durable workflow, awaits its outcome
/// (with cooperative cancellation), and mirrors `TokioRunner`'s session
/// semantics at the run boundary.
pub mod runner;
/// Temporal worker construction: builds a [`worker::TemporalAgentWorker`]
/// that serves one or more registered [`paigasus_helikon_core::LlmAgent`]s'
/// activities on a task queue.
pub mod worker;
/// The durable agent-loop workflow driven by a
/// [`crate::worker::TemporalAgentWorker`]. Internal: the public entry points
/// are [`worker::TemporalAgentWorker`] (worker side) and
/// [`runner::TemporalRunner`] (client side).
mod workflow;

