1	//! Permission layer: gate tool calls via deny rules → permission mode →
2	//! `canUseTool` policy. See the *Permissions, Guardrails & Hooks* concept page.
3	
4	use async_trait::async_trait;
5	
6	use crate::RunContext;
7	
8	/// How permission mode governs tool calls.
9	///
10	/// Transitions are **tighten-only**, enforced by
11	/// [`RunContext::with_permission_mode`]: `Bypass` never loosens (it may only
12	/// tighten to `DontAsk`), and `DontAsk` is terminal. Both propagate to
13	/// subagents — a typed enum, not a string.
14	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
15	#[non_exhaustive]
16	pub enum PermissionMode {
17	    /// Defer to the policy (ask for unfamiliar tools); permissive when no policy.
18	    #[default]
19	    Default,
20	    /// Auto-approve tools with a [`crate::ToolEffect::Write`] effect; all other
21	    /// tools still reach the policy.
22	    AcceptEdits,
23	    /// Read-only: deny any tool whose [`crate::ToolEffect`] is not `ReadOnly`.
24	    Plan,
25	    /// Dangerous: allow all (deny rules still apply). Propagates; sticky.
26	    Bypass,
27	    /// Locked-down headless inverse of `Bypass`: deny-by-default. The policy
28	    /// (`canUseTool`) is never invoked; only an [`crate::AllowRule`] (after
29	    /// the deny+guard steps) can permit a call. Sticky and terminal — once set
30	    /// it cannot be loosened.
31	    DontAsk,
32	}
33	
34	/// The outcome of a [`PermissionPolicy::check`] (or the resolved decision).
35	#[derive(Debug, Clone)]
36	#[non_exhaustive]
37	pub enum PermissionDecision {
38	    /// Run the call unchanged.
39	    Allow,
40	    /// Block the call; the reason is surfaced to the model as a tool result.
41	    Deny {
42	        /// Human-readable denial reason.
43	        reason: String,
44	    },
45	    /// Ask a human (resolved via [`ApprovalHandler`]; default Deny).
46	    AskUser {
47	        /// Prompt shown to the approver.
48	        prompt: String,
49	    },
50	    /// Replace the call's arguments before execution (sanitize).
51	    Replace {
52	        /// Replacement JSON arguments.
53	        args: serde_json::Value,
54	    },
55	}
56	
57	/// Authorizes a tool call. The decision pipeline runs
58	/// `deny rules › guard rules › allow rules › mode › this policy` (see
59	/// `control.rs`).
60	#[async_trait]
61	pub trait PermissionPolicy<Ctx>: Send + Sync
62	where
63	    Ctx: Send + Sync + 'static,
64	{
65	    /// Decide whether `tool` may run with `args`.
66	    async fn check(
67	        &self,
68	        ctx: &RunContext<Ctx>,
69	        tool: &str,
70	        args: &serde_json::Value,
71	    ) -> PermissionDecision;
72	}
73	
74	/// How a [`DenyRule`] matches a call.
75	#[derive(Debug, Clone, PartialEq, Eq)]
76	enum Matcher {
77	    /// Exact tool name.
78	    Tool(String),
79	    /// Any Bash sub-command whose resolved program equals this. Tool-scoped to
80	    /// the `Bash` tool.
81	    BashProgram(String),
82	    /// `Read` tool whose `path` arg matches this glob.
83	    ReadPath(crate::path_match::PathGlob),
84	    /// `Edit`/`Write` tool whose `path` arg matches this glob.
85	    EditPath(crate::path_match::PathGlob),
86	}
87	
88	/// A first-class deny rule, evaluated **before** mode — so it overrides even
89	/// [`PermissionMode::Bypass`].
90	#[derive(Debug, Clone, PartialEq, Eq)]
91	pub struct DenyRule {
92	    matcher: Matcher,
93	}
94	
95	impl DenyRule {
96	    /// Deny a tool by its exact name.
97	    pub fn tool(name: impl Into<String>) -> Self {
98	        Self {
99	            matcher: Matcher::Tool(name.into()),
100	        }
101	    }
102	
103	    /// Deny a Bash call whose compound command contains a sub-command whose
104	    /// resolved program equals `program` (operator-, wrapper-, and
105	    /// `bash -c`-aware). Only matches the `Bash` tool.
106	    pub fn bash_command(program: impl Into<String>) -> Self {
107	        Self {
108	            matcher: Matcher::BashProgram(program.into()),
109	        }
110	    }
111	
112	    /// Deny a `Read` whose `path` arg matches `pattern` (gitignore-style glob:
113	    /// no `/` matches at any depth, a `/` anchors to the path root,
114	    /// case-insensitive). Scoped to the `Read` tool only — does **not** match
115	    /// `Edit`/`Write`. Lexical and **advisory** — not a sandbox.
116	    pub fn read(pattern: impl Into<String>) -> Self {
117	        Self {
118	            matcher: Matcher::ReadPath(crate::path_match::PathGlob::new(pattern)),
119	        }
120	    }
121	
122	    /// Deny an `Edit`/`Write` whose `path` arg matches `pattern`.
123	    pub fn edit(pattern: impl Into<String>) -> Self {
124	        Self {
125	            matcher: Matcher::EditPath(crate::path_match::PathGlob::new(pattern)),
126	        }
127	    }
128	
129	    /// `true` if this rule denies `tool` invoked with `args`.
130	    pub fn matches(&self, tool: &str, args: &serde_json::Value) -> bool {
131	        match &self.matcher {
132	            Matcher::Tool(name) => name == tool,
133	            Matcher::BashProgram(program) => {
134	                if tool != "Bash" {
135	                    return false;
136	                }
137	                let Some(command) = args.get("command").and_then(|v| v.as_str()) else {
138	                    return false;
139	                };
140	                crate::command_match::resolve_all(command)
141	                    .iter()
142	                    .any(|c| &c.program == program)
143	            }
144	            Matcher::ReadPath(glob) => path_arg_matches(tool, args, PathKind::Read, glob),
145	            Matcher::EditPath(glob) => path_arg_matches(tool, args, PathKind::Edit, glob),
146	        }
147	    }
148	}
149	
150	/// Which tool family a path-rule applies to.
151	#[derive(Clone, Copy)]
152	enum PathKind {
153	    Read,
154	    Edit,
155	}
156	
157	/// `true` if `tool` is in `kind`'s family and its `path` arg matches `glob`.
158	/// `Read` → tool `"Read"`; `Edit` → tools `"Edit"` and `"Write"`.
159	fn path_arg_matches(
160	    tool: &str,
161	    args: &serde_json::Value,
162	    kind: PathKind,
163	    glob: &crate::path_match::PathGlob,
164	) -> bool {
165	    let applies = match kind {
166	        PathKind::Read => tool == "Read",
167	        PathKind::Edit => tool == "Edit" || tool == "Write",
168	    };
169	    if !applies {
170	        return false;
171	    }
172	    args.get("path")
173	        .and_then(|v| v.as_str())
174	        .map(|p| glob.matches_path(p))
175	        .unwrap_or(false)
176	}
177	
178	/// How an [`AllowRule`] matches a call.
179	#[derive(Debug, Clone, PartialEq, Eq)]
180	enum AllowMatcher {
181	    /// Exact tool name.
182	    Tool(String),
183	    /// Bash call where **every** sub-command's program equals this (fail-closed).
184	    BashProgram(String),
185	    /// `Read` tool whose `path` arg matches this glob.
186	    ReadPath(crate::path_match::PathGlob),
187	    /// `Edit`/`Write` tool whose `path` arg matches this glob.
188	    EditPath(crate::path_match::PathGlob),
189	}
190	
191	/// A positive permission rule: a **global, all-modes, per-tool/per-command
192	/// pre-approval**. When an allow rule matches, the call is allowed in *every*
193	/// mode and `canUseTool` is **not** consulted for it (the deny and guard steps
194	/// still run first). Prefer [`AllowRule::bash_command`] over
195	/// `AllowRule::tool("Bash")` so a single allowed program does not disable all
196	/// Bash policy checks. Evaluated after deny + guard, before mode (see
197	/// `control.rs`).
198	#[derive(Debug, Clone, PartialEq, Eq)]
199	pub struct AllowRule {
200	    matcher: AllowMatcher,
201	}
202	
203	impl AllowRule {
204	    /// Allow a tool by its exact name.
205	    pub fn tool(name: impl Into<String>) -> Self {
206	        Self {
207	            matcher: AllowMatcher::Tool(name.into()),
208	        }
209	    }
210	
211	    /// Allow a Bash call **only when every** resolved sub-command's program
212	    /// equals `program` (operator-, wrapper-, `bash -c`-aware). A compound
213	    /// command with any other program does not match (fail-closed). Only the
214	    /// `Bash` tool. v1 does not compose multiple `bash_command` allows across a
215	    /// single compound command.
216	    pub fn bash_command(program: impl Into<String>) -> Self {
217	        Self {
218	            matcher: AllowMatcher::BashProgram(program.into()),
219	        }
220	    }
221	
222	    /// Allow a `Read` whose `path` arg matches `pattern` (same gitignore-style
223	    /// glob semantics as [`DenyRule::read`]). Scoped to the `Read` tool only —
224	    /// does **not** match `Edit`/`Write`. Advisory, not a sandbox.
225	    pub fn read(pattern: impl Into<String>) -> Self {
226	        Self {
227	            matcher: AllowMatcher::ReadPath(crate::path_match::PathGlob::new(pattern)),
228	        }
229	    }
230	
231	    /// Allow an `Edit`/`Write` whose `path` arg matches `pattern`.
232	    pub fn edit(pattern: impl Into<String>) -> Self {
233	        Self {
234	            matcher: AllowMatcher::EditPath(crate::path_match::PathGlob::new(pattern)),
235	        }
236	    }
237	
238	    /// `true` if this rule allows `tool` invoked with `args`.
239	    pub fn matches(&self, tool: &str, args: &serde_json::Value) -> bool {
240	        match &self.matcher {
241	            AllowMatcher::Tool(name) => name == tool,
242	            AllowMatcher::BashProgram(program) => {
243	                if tool != "Bash" {
244	                    return false;
245	                }
246	                let Some(command) = args.get("command").and_then(|v| v.as_str()) else {
247	                    return false;
248	                };
249	                let subs = crate::command_match::resolve_all(command);
250	                !subs.is_empty() && subs.iter().all(|c| &c.program == program)
251	            }
252	            AllowMatcher::ReadPath(glob) => path_arg_matches(tool, args, PathKind::Read, glob),
253	            AllowMatcher::EditPath(glob) => path_arg_matches(tool, args, PathKind::Edit, glob),
254	        }
255	    }
256	}
257	
258	/// Resolves a [`PermissionDecision::AskUser`] when the driver cannot decide
259	/// inline. Non-generic — it needs no `Ctx`.
260	#[async_trait]
261	pub trait ApprovalHandler: Send + Sync {
262	    /// Decide an `AskUser` prompt. Returns a narrowed [`ApprovalOutcome`]
263	    /// (cannot recursively ask).
264	    async fn decide(&self, tool: &str, prompt: &str, args: &serde_json::Value) -> ApprovalOutcome;
265	}
266	
267	/// The narrowed decision an [`ApprovalHandler`] may return.
268	#[derive(Debug, Clone)]
269	#[non_exhaustive]
270	pub enum ApprovalOutcome {
271	    /// Allow the call.
272	    Allow,
273	    /// Deny the call with a reason.
274	    Deny {
275	        /// Human-readable denial reason.
276	        reason: String,
277	    },
278	}
279	
280	/// The action a tripped [`GuardRule`] takes. Evaluated **before** mode, so it
281	/// overrides even [`PermissionMode::Bypass`].
282	#[derive(Debug, Clone, PartialEq, Eq)]
283	#[non_exhaustive]
284	pub enum GuardAction {
285	    /// Hard-deny with a reason.
286	    Deny {
287	        /// Human-readable denial reason.
288	        reason: String,
289	    },
290	    /// Ask a human via the [`ApprovalHandler`] (default Deny when none).
291	    Ask {
292	        /// Prompt shown to the approver.
293	        prompt: String,
294	    },
295	}
296	
297	#[derive(Debug, Clone, PartialEq, Eq)]
298	enum GuardMatcher {
299	    /// `rm` with recursive+force flags targeting `/` or `~` (literal).
300	    RmRecursiveRootOrHome,
301	    /// A write whose target resolves under a protected prefix (Bash redirects,
302	    /// `tee`/`dd`, or the Write/Edit `path` arg). Honors the device-node allowlist.
303	    ProtectedPathWrite,
304	    /// A write whose target has a `.git`/`.ssh` path component or a `.env`(`.env.*`)
305	    /// final component (Bash redirects, `tee`/`dd`, or the Write/Edit `path` arg).
306	    ProtectedDotPathWrite,
307	}
308	
309	/// A pre-mode safety rule. Like [`DenyRule`] it runs before permission mode and
310	/// beats `Bypass`, but it may **ask** a human instead of hard-denying.
311	#[derive(Debug, Clone, PartialEq, Eq)]
312	pub struct GuardRule {
313	    matcher: GuardMatcher,
314	    action: GuardAction,
315	}
316	
317	/// Protected path prefixes. A write resolving under any of these trips
318	/// [`GuardMatcher::ProtectedPathWrite`].
319	const PROTECTED_PREFIXES: &[&str] = &["/etc", "/usr", "/bin", "/sbin", "/sys", "/boot", "/dev"];
320	
321	/// Device nodes that are safe write targets despite the `/dev` prefix. Checked
322	/// before the protected-prefix rule so `cmd > /dev/null` is never denied.
323	const DEVICE_ALLOWLIST: &[&str] = &[
324	    "/dev/null",
325	    "/dev/zero",
326	    "/dev/full",
327	    "/dev/stdout",
328	    "/dev/stderr",
329	    "/dev/tty",
330	    "/dev/random",
331	    "/dev/urandom",
332	];
333	
334	impl GuardRule {
335	    /// The action this rule takes when it matches.
336	    pub fn action(&self) -> &GuardAction {
337	        &self.action
338	    }
339	
340	    /// `true` if this guard trips for `tool` invoked with `args`.
341	    pub fn matches(&self, tool: &str, args: &serde_json::Value) -> bool {
342	        match &self.matcher {
343	            GuardMatcher::RmRecursiveRootOrHome => {
344	                let Some(cmd) = bash_command_str(tool, args) else {
345	                    return false;
346	                };
347	                crate::command_match::resolve_all(cmd)
348	                    .iter()
349	                    .any(is_rm_rf_root_or_home)
350	            }
351	            GuardMatcher::ProtectedPathWrite => protected_path_write(tool, args),
352	            GuardMatcher::ProtectedDotPathWrite => protected_dotpath_write(tool, args),
353	        }
354	    }
355	
356	    /// The always-on destructive guard set: `rm -rf /`, `rm -rf ~`, and
357	    /// protected-path writes. All default to [`GuardAction::Ask`].
358	    pub fn destructive_defaults() -> Vec<GuardRule> {
359	        vec![
360	            GuardRule {
361	                matcher: GuardMatcher::RmRecursiveRootOrHome,
362	                action: GuardAction::Ask {
363	                    prompt: "destructive command: recursive force-remove of / or ~".to_owned(),
364	                },
365	            },
366	            GuardRule {
367	                matcher: GuardMatcher::ProtectedPathWrite,
368	                action: GuardAction::Ask {
369	                    prompt: "write to a protected system path".to_owned(),
370	                },
371	            },
372	            GuardRule {
373	                matcher: GuardMatcher::ProtectedDotPathWrite,
374	                action: GuardAction::Ask {
375	                    prompt: "write to a protected VCS/secret path (.git, .ssh, .env)".to_owned(),
376	                },
377	            },
378	        ]
379	    }
380	}
381	
382	fn bash_command_str<'a>(tool: &str, args: &'a serde_json::Value) -> Option<&'a str> {
383	    if tool != "Bash" {
384	        return None;
385	    }
386	    args.get("command").and_then(|v| v.as_str())
387	}
388	
389	fn is_rm_rf_root_or_home(cmd: &crate::command_match::ResolvedCommand) -> bool {
390	    if cmd.program != "rm" {
391	        return false;
392	    }
393	    let mut recursive = false;
394	    let mut force = false;
395	    let mut targets: Vec<&str> = Vec::new();
396	    for a in &cmd.args {
397	        if a.starts_with("--") {
398	            match a.as_str() {
399	                "--recursive" => recursive = true,
400	                "--force" => force = true,
401	                _ => {}
402	            }
403	        } else if let Some(flags) = a.strip_prefix('-') {
404	            if flags.contains('r') || flags.contains('R') {
405	                recursive = true;
406	            }
407	            if flags.contains('f') {
408	                force = true;
409	            }
410	        } else {
411	            targets.push(a);
412	        }
413	    }
414	    recursive && force && targets.iter().any(|t| is_root_or_home(t))
415	}
416	
417	fn is_root_or_home(target: &str) -> bool {
418	    matches!(target, "/" | "/*" | "~" | "~/" | "${HOME}" | "$HOME")
419	}
420	
421	fn protected_path_write(tool: &str, args: &serde_json::Value) -> bool {
422	    if matches!(tool, "Write" | "Edit") {
423	        if let Some(p) = args.get("path").and_then(|v| v.as_str()) {
424	            return is_protected_path(p);
425	        }
426	    }
427	    if let Some(cmd) = bash_command_str(tool, args) {
428	        for c in crate::command_match::resolve_all(cmd) {
429	            for r in &c.redirects {
430	                use crate::command_match::RedirectOp;
431	                if matches!(r.op, RedirectOp::Out | RedirectOp::Append)
432	                    && is_protected_path(&r.target)
433	                {
434	                    return true;
435	                }
436	            }
437	            if c.program == "tee" && c.args.iter().any(|a| is_protected_path(a)) {
438	                return true;
439	            }
440	            if c.program == "dd" {
441	                if let Some(of) = c.args.iter().find_map(|a| a.strip_prefix("of=")) {
442	                    if is_protected_path(of) {
443	                        return true;
444	                    }
445	                }
446	            }
447	        }
448	    }
449	    false
450	}
451	
452	fn protected_dotpath_write(tool: &str, args: &serde_json::Value) -> bool {
453	    if matches!(tool, "Write" | "Edit") {
454	        if let Some(p) = args.get("path").and_then(|v| v.as_str()) {
455	            if crate::path_match::is_protected_dotpath(p) {
456	                return true;
457	            }
458	        }
459	    }
460	    if let Some(cmd) = bash_command_str(tool, args) {
461	        for c in crate::command_match::resolve_all(cmd) {
462	            for r in &c.redirects {
463	                use crate::command_match::RedirectOp;
464	                if matches!(r.op, RedirectOp::Out | RedirectOp::Append)
465	                    && crate::path_match::is_protected_dotpath(&r.target)
466	                {
467	                    return true;
468	                }
469	            }
470	            if c.program == "tee"
471	                && c.args
472	                    .iter()
473	                    .any(|a| crate::path_match::is_protected_dotpath(a))
474	            {
475	                return true;
476	            }
477	            if c.program == "dd" {
478	                if let Some(of) = c.args.iter().find_map(|a| a.strip_prefix("of=")) {
479	                    if crate::path_match::is_protected_dotpath(of) {
480	                        return true;
481	                    }
482	                }
483	            }
484	        }
485	    }
486	    false
487	}
488	
489	fn is_protected_path(path: &str) -> bool {
490	    if DEVICE_ALLOWLIST.contains(&path) {
491	        return false;
492	    }
493	    if path == "/" {
494	        return true;
495	    }
496	    PROTECTED_PREFIXES
497	        .iter()
498	        .any(|p| path == *p || path.starts_with(&format!("{p}/")))
499	}
