1	//! Temporal worker construction.
2	//!
3	//! [`crate::worker::TemporalAgentWorker`] wraps a `temporalio_sdk::Worker`
4	//! configured to serve one or more registered
5	//! [`paigasus_helikon_core::LlmAgent`]s' activities on a task queue. Build
6	//! one via [`crate::worker::TemporalAgentWorker::builder`].
7	//!
8	//! # Workflow registration (SMA-332 Task 8)
9	//!
10	//! [`crate::worker::TemporalAgentWorkerBuilder::build`] registers the durable
11	//! agent-loop workflow (the crate-internal `workflow` module) via
12	//! `register_workflow_with_factory`, because `build()` is the last point at
13	//! which `Ctx` is still in scope. The workflow itself is `Ctx`-free (it plans
14	//! against a `Ctx`-free `HashMap<String, AgentPlan>` projected from the
15	//! registry), so the factory closes over an
16	//! `Arc<crate::workflow::WorkflowActivityConfig>` — never a serialized plan
17	//! and never a `Ctx`-generic value. The constructed `temporalio_sdk::Worker`
18	//! type-erases every registered activity/workflow, so
19	//! [`crate::worker::TemporalAgentWorker`] carries no `Ctx` parameter.
20	
21	use std::collections::HashMap;
22	use std::sync::Arc;
23	use std::time::Duration;
24	
25	use paigasus_helikon_core::{
26	    AllowRule, ApprovalHandler, DenyRule, GuardRule, LlmAgent, Model, PermissionMode,
27	    PermissionPolicy, RunContext, ToolDef,
28	};
29	
30	use crate::activities::{self, DurableAgentDef};
31	use crate::driver::AgentPlan;
32	
33	/// Floor applied to [`TemporalAgentWorkerBuilder::heartbeat_interval`] so a
34	/// caller can't configure a heartbeat interval so tight it turns into an
35	/// activity-heartbeat storm.
36	const MIN_HEARTBEAT_INTERVAL: Duration = Duration::from_secs(1);
37	
38	/// Worker-side security posture applied to every `RunContext` the durable
39	/// activities fabricate. `Default` reproduces the crate's v0 fixed defaults
40	/// (`PermissionMode::Default`, built-in destructive guards on, output redaction
41	/// on, no custom rules / policy / approval handler / extra secrets).
42	pub struct WorkerPosture<Ctx: Send + Sync + 'static> {
43	    permission_mode: PermissionMode,
44	    deny_rules: Vec<DenyRule>,
45	    allow_rules: Vec<AllowRule>,
46	    guard_rules: Vec<GuardRule>,
47	    permission_policy: Option<Arc<dyn PermissionPolicy<Ctx>>>,
48	    approval_handler: Option<Arc<dyn ApprovalHandler>>,
49	    default_guards: bool,
50	    redact_output: bool,
51	    extra_secrets: Vec<String>,
52	}
53	
54	impl<Ctx: Send + Sync + 'static> Default for WorkerPosture<Ctx> {
55	    fn default() -> Self {
56	        Self {
57	            permission_mode: PermissionMode::default(),
58	            deny_rules: Vec::new(),
59	            allow_rules: Vec::new(),
60	            guard_rules: Vec::new(),
61	            permission_policy: None,
62	            approval_handler: None,
63	            default_guards: true,
64	            redact_output: true,
65	            extra_secrets: Vec::new(),
66	        }
67	    }
68	}
69	
70	impl<Ctx: Send + Sync + 'static> WorkerPosture<Ctx> {
71	    /// Set the permission mode the activities enforce (tighten-only from `Default`).
72	    pub fn with_permission_mode(mut self, mode: PermissionMode) -> Self {
73	        self.permission_mode = mode;
74	        self
75	    }
76	    /// Install deny rules (evaluated before mode; override even `Bypass`).
77	    pub fn with_deny_rules(mut self, rules: Vec<DenyRule>) -> Self {
78	        self.deny_rules = rules;
79	        self
80	    }
81	    /// Install allow rules (positive short-circuit in any mode).
82	    pub fn with_allow_rules(mut self, rules: Vec<AllowRule>) -> Self {
83	        self.allow_rules = rules;
84	        self
85	    }
86	    /// Install user guard rules (evaluated before mode; may ask or deny).
87	    pub fn with_guard_rules(mut self, rules: Vec<GuardRule>) -> Self {
88	        self.guard_rules = rules;
89	        self
90	    }
91	    /// Install the `canUseTool` permission policy. It can read the per-run
92	    /// (seeded) `RunContext::user_ctx` for request-scoped decisions.
93	    pub fn with_permission_policy(mut self, policy: Arc<dyn PermissionPolicy<Ctx>>) -> Self {
94	        self.permission_policy = Some(policy);
95	        self
96	    }
97	    /// Install the approval handler that resolves `AskUser` / guard `Ask` decisions.
98	    pub fn with_approval_handler(mut self, handler: Arc<dyn ApprovalHandler>) -> Self {
99	        self.approval_handler = Some(handler);
100	        self
101	    }
102	    /// Disable the always-on built-in destructive guard set (power-user opt-out).
103	    pub fn without_default_guards(mut self) -> Self {
104	        self.default_guards = false;
105	        self
106	    }
107	    /// Disable automatic secret redaction of tool output. Note: unredacted tool
108	    /// output then enters permanent Temporal history.
109	    pub fn without_output_redaction(mut self) -> Self {
110	        self.redact_output = false;
111	        self
112	    }
113	    /// Add extra secret values to redact from tool output, beyond the env set.
114	    pub fn with_extra_secrets(mut self, secrets: Vec<String>) -> Self {
115	        self.extra_secrets = secrets;
116	        self
117	    }
118	
119	    /// Apply this posture onto a freshly fabricated `RunContext`.
120	    ///
121	    /// NB: this is the **fifth** hand-copy of core's nine-field permission
122	    /// bundle (see `RunContext`'s fields and core's `pub(crate) PermissionFields`).
123	    /// `PermissionFields` cannot be reused across the crate boundary. If core
124	    /// gains a tenth posture knob, add it here too — the default-equivalence
125	    /// unit test enumerates every field to catch the omission.
126	    pub(crate) fn apply(&self, ctx: RunContext<Ctx>) -> RunContext<Ctx> {
127	        let mut ctx = ctx
128	            .with_permission_mode(self.permission_mode)
129	            .with_deny_rules(self.deny_rules.clone())
130	            .with_allow_rules(self.allow_rules.clone())
131	            .with_guard_rules(self.guard_rules.clone())
132	            .with_extra_secrets(self.extra_secrets.clone());
133	        if let Some(p) = &self.permission_policy {
134	            ctx = ctx.with_permission_policy(Arc::clone(p));
135	        }
136	        if let Some(h) = &self.approval_handler {
137	            ctx = ctx.with_approval_handler(Arc::clone(h));
138	        }
139	        if !self.default_guards {
140	            ctx = ctx.without_default_guards();
141	        }
142	        if !self.redact_output {
143	            ctx = ctx.without_output_redaction();
144	        }
145	        ctx
146	    }
147	}
