149	/// Retry-policy knobs applied to a durable agent's `call_model`/`invoke_tool`
150	/// activity invocations.
151	///
152	/// `None`/empty fields mean "use the Temporal server's own defaults" — this
153	/// type intentionally does not carry Temporal's raw
154	/// `temporal.api.common.v1::RetryPolicy` proto shape; SMA-332 Task 8, which
155	/// is the first consumer that actually builds an `ActivityOptions` to attach
156	/// a retry policy to, converts a [`RetryPolicyConfig`] into that proto type
157	/// at the point of use.
158	#[derive(Debug, Clone, Default)]
159	pub struct RetryPolicyConfig {
160	    /// Interval before the first retry.
161	    pub initial_interval: Option<std::time::Duration>,
162	    /// Multiplier applied to the previous retry interval. Must be `>= 1.0`
163	    /// when set.
164	    pub backoff_coefficient: Option<f64>,
165	    /// Cap on the backed-off retry interval.
166	    pub maximum_interval: Option<std::time::Duration>,
167	    /// Maximum retry attempts. `Some(1)` disables retries; `Some(0)` or
168	    /// `None` means unlimited (bounded only by activity timeouts).
169	    pub maximum_attempts: Option<u32>,
170	    /// Error type names that must not be retried.
171	    pub non_retryable_error_types: Vec<String>,
172	}
173	
174	/// Why a seeded `Ctx` factory rejected a run's seed. Surfaced as a
175	/// **non-retryable** activity failure so a malformed/hostile seed fails the run
176	/// fast instead of retry-looping.
177	#[derive(Debug, thiserror::Error)]
178	#[error("{0}")]
179	pub struct CtxSeedError(String);
